    66	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
    67	  <div class="keys">
    68	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open parenthesis">(</button>
    69	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close parenthesis">)</button>
    70	
    71	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
    72	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
    73	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
    74	
    75	    <button data-testid="key-7" data-digit="7">7</button>
    76	    <button data-testid="key-8" data-digit="8">8</button>
    77	    <button data-testid="key-9" data-digit="9">9</button>
    78	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
    79	
    80	    <button data-testid="key-4" data-digit="4">4</button>
    81	    <button data-testid="key-5" data-digit="5">5</button>
    82	    <button data-testid="key-6" data-digit="6">6</button>
    83	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
    84	
    85	    <button data-testid="key-1" data-digit="1">1</button>
    86	    <button data-testid="key-2" data-digit="2">2</button>
    87	    <button data-testid="key-3" data-digit="3">3</button>
    88	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
    89	
    90	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
    91	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
    92	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
    93	  </div>
    94	</div>
    95	<script>
    96	(function () {
    97	  var display = document.querySelector('[data-testid="calc-display"]');
    98	  var opButtons = document.querySelectorAll('[data-op]');
    99	
   100	  // entry: string being typed, or null when showing a stored value.
   101	  // value: number currently shown when entry is null.
   102	  // operand: true when value came from ± or ) and is the next operand, like
   103	  // a typed entry, but further digits start a new entry instead of appending.
   104	  // groups: one saved { stored, op } per open parenthesis, innermost last.
   105	  var state;
   106	
   107	  function reset() {
   108	    state = { entry: null, value: 0, stored: null, op: null, operand: false, error: false, groups: [] };
   109	  }
   110	
   111	  function compute(a, op, b) {
   112	    switch (op) {
   113	      case '+': return a + b;
   114	      case '-': return a - b;
   115	      case '*': return a * b;
   116	      case '/': return a / b;
   117	    }
   118	    return b;
   119	  }
   120	
   121	  function currentNumber() {
   122	    return state.entry !== null ? parseFloat(state.entry) : state.value;
   123	  }
   124	
   125	  // Presentation only: round to at most 10 significant digits for the visible
   126	  // text. The stored value is never rounded, so chains stay exact.
   127	  // Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
   128	  function formatValue(n) {
   129	    if (n === 0) return '0';
   130	    var parts = Math.abs(n).toExponential(9).split('e');
   131	    var digits = parts[0].replace('.', '');
   132	    var exp = parseInt(parts[1], 10);
   133	    var sign = n < 0 ? '-' : '';
   134	    if (exp >= 10 || exp < -9) {
   135	      var mantissa = trimFraction(digits.charAt(0), digits.slice(1));
   136	      return sign + mantissa + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
   137	    }
   138	    if (exp >= 0) {
   139	      return sign + trimFraction(digits.slice(0, exp + 1), digits.slice(exp + 1));
   140	    }
   141	    return sign + trimFraction('0', new Array(-exp).join('0') + digits);
   142	  }
   143	
   144	  function trimFraction(intPart, frac) {
   145	    frac = frac.replace(/0+$/, '');
   146	    return frac ? intPart + '.' + frac : intPart;
   147	  }
   148	
   149	  function render() {
   150	    var text;
   151	    if (state.error) {
   152	      text = 'Error';
   153	    } else if (state.entry !== null) {
   154	      text = state.entry;
   155	    } else {
   156	      text = formatValue(state.value);
   157	    }
   158	    display.textContent = text;
   159	    display.setAttribute('data-value', state.error ? 'NaN' : String(currentNumber()));
   160	    display.setAttribute('data-error', state.error ? 'true' : 'false');
   161	
   162	    var len = text.length;
   163	    display.style.fontSize = len > 16 ? '20px' : len > 12 ? '28px' : len > 9 ? '36px' : '48px';
   164	
   165	    for (var i = 0; i < opButtons.length; i++) {
   166	      var b = opButtons[i];
   167	      b.classList.toggle('active', state.entry === null && !state.operand && state.op === b.getAttribute('data-op'));
   168	    }
   169	  }
   170	
   171	  // In the error state every key except clear is ignored.
   172	  function inputDigit(d) {
   173	    if (state.error) return;
   174	    state.operand = false;
   175	    if (state.entry === null || state.entry === '0') {
   176	      state.entry = d;
   177	    } else if (state.entry === '-0') {
   178	      state.entry = '-' + d;
   179	    } else {
   180	      state.entry += d;
   181	    }
   182	  }
   183	
   184	  function inputDot() {
   185	    if (state.error) return;
   186	    state.operand = false;
   187	    if (state.entry === null) {
   188	      state.entry = '0.';
   189	    } else if (state.entry.indexOf('.') === -1) {
   190	      state.entry += '.';
   191	    }
   192	  }
   193	
   194	  // ± acts on the shown number at once. A typed entry keeps its text,
   195	  // so 0 ± 5 gives -5.
   196	  function inputSign() {
   197	    if (state.error) return;
   198	    if (state.entry !== null) {
   199	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
   200	    } else {
   201	      state.value = -state.value;
   202	      state.operand = true;
   203	    }
   204	  }
   205	
   206	  function setResult(n) {
   207	    if (!isFinite(n)) {
   208	      reset();
   209	      state.error = true;
   210	      return;
   211	    }
   212	    state.value = n;
   213	  }
   214	
   215	  // Immediate execution, strictly left to right, no operator precedence:
   216	  // an operator key first applies the operation already waiting, so the
   217	  // display always shows a real running result. 2 + 3 × 4 = is 20, not 14.
   218	  function inputOp(op) {
   219	    if (state.error) return;
   220	    if (state.entry !== null || state.operand) {
   221	      var n = currentNumber();
   222	      state.entry = null;
   223	      state.operand = false;
   224	      if (state.op !== null && state.stored !== null) {
   225	        setResult(compute(state.stored, state.op, n));
   226	        if (state.error) return;
   227	      } else {
   228	        state.value = n;
   229	      }
   230	    }
   231	    state.stored = state.value;
   232	    state.op = op;
   233	  }
   234	
   235	  // Finish the operation waiting at the current level, as = does.
   236	  function finishLevel() {
   237	    state.operand = false;
   238	    if (state.op === null) {
   239	      if (state.entry !== null) {
   240	        state.value = parseFloat(state.entry);
   241	        state.entry = null;
   242	      }
   243	      return;
   244	    }
   245	    var b = currentNumber();
   246	    state.entry = null;
   247	    var op = state.op;
   248	    state.op = null;
   249	    var a = state.stored;
   250	    state.stored = null;
   251	    setResult(compute(a, op, b));
   252	  }
   253	
   254	  // ( saves the waiting operation and starts a fresh one inside the group.
   255	  // Right after a number, ( multiplies it by the group: 2 ( 3 ) is 6.
   256	  function openGroup() {
   257	    if (state.error) return;
   258	    if (state.entry !== null || state.operand) {
   259	      inputOp('*');
   260	      if (state.error) return;
   261	    }
   262	    state.groups.push({ stored: state.stored, op: state.op });
   263	    state.entry = null;
   264	    state.value = 0;
   265	    state.stored = null;
   266	    state.op = null;
   267	    state.operand = false;
   268	  }
   269	
   270	  // ) finishes the group and hands its result back as the next operand.
   271	  function closeGroup() {
   272	    if (state.error || state.groups.length === 0) return;
   273	    finishLevel();
   274	    if (state.error) return;
   275	    var outer = state.groups.pop();
   276	    state.stored = outer.stored;
   277	    state.op = outer.op;
   278	    state.operand = true;
   279	  }
   280	
   281	  // = closes any groups still open, then finishes the calculation.
   282	  function equals() {
   283	    if (state.error) return;
   284	    while (state.groups.length > 0) {
   285	      closeGroup();
   286	      if (state.error) return;
   287	    }
   288	    finishLevel();
   289	  }
   290	
   291	  document.querySelector('.keys').addEventListener('click', function (e) {
   292	    var btn = e.target.closest('button');
   293	    if (!btn) return;
   294	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
   295	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
   296	    else {
   297	      var action = btn.getAttribute('data-action');
   298	      if (action === 'dot') inputDot();
   299	      else if (action === 'sign') inputSign();
   300	      else if (action === 'lparen') openGroup();
   301	      else if (action === 'rparen') closeGroup();
   302	      else if (action === 'equals') equals();
   303	      else if (action === 'clear') reset();
   304	    }
   305	    render();
   306	  });
   307	
   308	  document.addEventListener('keydown', function (e) {
   309	    if (e.ctrlKey || e.metaKey || e.altKey) return;
   310	    var k = e.key;
   311	    if (/^[0-9]$/.test(k)) inputDigit(k);
   312	    else if (k === '.' || k === ',') inputDot();
   313	    else if (k === '+' || k === '-' || k === '*' || k === '/') inputOp(k);
   314	    else if (k === '(') openGroup();
   315	    else if (k === ')') closeGroup();
   316	    else if (k === 'Enter' || k === '=') equals();
   317	    else if (k === 'Escape' || k === 'c' || k === 'C') reset();
   318	    else return;
   319	    e.preventDefault();
   320	    render();
   321	  });
   322	
   323	  reset();
   324	  render();
   325	})();
   326	</script>
   327	</body>
   328	</html>
